<script>
  import Markdown from './Markdown/Markdown.svelte'
  import { resolveImage } from './image.js'

  let {
    class: klass = '',
    figureClass = undefined,
    figure = true,
    caption = undefined,
    captionClass = undefined,
    picture = true,
    pictureClass = undefined,
    src,
    alt = '',
    loading = 'lazy',
    ...rest
  } = $props()

  const image = $derived(resolveImage(src))
  const isGif = $derived(image.format === 'gif' || image.src?.includes('.gif'))
  const usePicture = $derived(picture && !isGif)
</script>

{#snippet img()}
  <img
    class="{klass} image media"
    {alt}
    height={image.height}
    {loading}
    src={image.src}
    srcset={image.srcset}
    width={image.width}
    {...rest}
  />
{/snippet}

{#snippet media()}
  {#if usePicture}
    <picture class={pictureClass}>
      {@render img()}
    </picture>
  {:else}
    {@render img()}
  {/if}
{/snippet}

{#if figure}
  <figure class={figureClass}>
    {@render media()}
    {#if caption}
      <figcaption class={captionClass}>
        <Markdown content={caption} inline />
      </figcaption>
    {/if}
  </figure>
{:else}
  {@render media()}
{/if}
